// MCN API client — generated by `mcn build --target flutter`.
// Talks to the MCN backend (`mcn serve`). Set the address with
//   flutter run --dart-define=MCN_API_URL=http://192.168.1.20:8080
// (default: 10.0.2.2:8080, which is your computer from the Android emulator).
import 'dart:convert';

import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';

const String apiBase =
    String.fromEnvironment('MCN_API_URL', defaultValue: 'http://10.0.2.2:8080');

/// Error from an MCN endpoint. [fieldErrors] maps field names to messages.
class ApiError implements Exception {
  ApiError(this.status, this.data);

  final int status;
  final dynamic data;

  String get message {
    final d = data;
    if (d is Map && d['error'] != null) return d['error'].toString();
    return 'Request failed ($status)';
  }

  Map<String, String> get fieldErrors {
    final d = data;
    if (d is Map && d['errors'] is Map) {
      return (d['errors'] as Map)
          .map((k, v) => MapEntry(k.toString(), v.toString()));
    }
    return const {};
  }

  @override
  String toString() => message;
}

class Api {
  Api._();

  static final Api instance = Api._();

  String? _token;

  /// Called when the server says the session is no longer valid.
  void Function()? onUnauthorized;

  String? get token => _token;

  Future<void> loadToken() async {
    final prefs = await SharedPreferences.getInstance();
    _token = prefs.getString('mcn_token');
  }

  Future<void> setToken(String? token) async {
    _token = token;
    final prefs = await SharedPreferences.getInstance();
    if (token == null) {
      await prefs.remove('mcn_token');
    } else {
      await prefs.setString('mcn_token', token);
    }
  }

  /// Absolute URL for a backend path (e.g. a signed file link).
  String url(String path) => path.startsWith('http') ? path : '$apiBase$path';

  Future<dynamic> get(String path, [Map<String, String>? query]) {
    var uri = Uri.parse(url(path));
    if (query != null && query.isNotEmpty) {
      uri = uri.replace(queryParameters: {...uri.queryParameters, ...query});
    }
    return _send(() => http.get(uri, headers: _headers()));
  }

  Future<dynamic> post(String path, [Object? body]) {
    return _send(() => http.post(Uri.parse(url(path)),
        headers: _headers(), body: jsonEncode(body ?? <String, dynamic>{})));
  }

  /// Call an MCN endpoint with positional arguments, like the web UI:
  /// `invoke('create_task', [title])`.
  Future<dynamic> invoke(String endpoint, [List<dynamic> args = const []]) {
    return post('/$endpoint',
        args.isEmpty ? <String, dynamic>{} : <String, dynamic>{'_args': args});
  }

  Map<String, String> _headers() => {
        'Content-Type': 'application/json',
        if (_token != null) 'Authorization': 'Bearer $_token',
      };

  Future<dynamic> _send(Future<http.Response> Function() request) async {
    final res = await request();
    dynamic data;
    try {
      data = res.bodyBytes.isEmpty ? null : jsonDecode(utf8.decode(res.bodyBytes));
    } catch (_) {
      data = {'error': res.body};
    }
    if (res.statusCode == 401 && _token != null) onUnauthorized?.call();
    if (res.statusCode >= 400) throw ApiError(res.statusCode, data);
    return data;
  }
}

final Api api = Api.instance;
